import SwiftUI
// NativuePlugins: nativue and the native side of the app's packages (generated by the nativue CLI)
import NativuePlugins

@main
struct MainApp: App {
    @UIApplicationDelegateAdaptor(NativueAppDelegate.self) private var appDelegate

    init() {
        NativueAppDelegate.plugins = nativuePlugins
    }

    var body: some Scene {
        WindowGroup {
            NativueView(plugins: nativuePlugins)
        }
    }
}
